/* Browser-local hospitality journey. All actions are demonstrations. */
const experienceState={request:null,feedback:null,rating:0,soldOut:false,events:[],ownerTab:'overview',guestTracking:false};
const originalRender=render, originalPlaceOrder=placeOrder, originalShowExtra=showExtra, originalRenderTour=renderTour;
const chapterOrder=[0,1,2,5,6,7,4,3];
scenes[0]=['A full house.<br>A calmer service.','One table. One connected journey. Try it below.'];
scenes[1]=['An appetite for<br>a little more.','Clear prices. Optional pairings. No order re-entry.'];
scenes[2]=['One order.<br>Everyone in the loop.','Guest, kitchen and owner share the same status.'];
scenes[3]=['Let the atmosphere<br>do the inviting.','Explore the café and kitchen before booking a seat.'];
scenes[4]=['See the shift.<br>Spot the opportunity.','Orders, requests and feedback in one place.'];
scenes.push(['A little help.<br>Without the hand-waving.','A table-specific request goes straight to the team.'],['The bill is ready.<br>Whenever they are.','Itemised, transparent and ready to keep digitally.'],['Every visit says<br>something. Listen.','Feedback reaches the owner while it’s still useful.']);
const outcomes={0:['LESS REPETITIVE WORK','Let your team host.','Guests can order themselves; staff stay available to help.'],1:['A REVENUE OPPORTUNITY','Make the extra easy to discover.','Optional pairings add a clear, guest-controlled selling moment.'],2:['FEWER STATUS CHASES','Know what needs attention.','A shared order status replaces repeated trips to the kitchen.'],3:['BEFORE THE FIRST VISIT','Turn curiosity into a visit.','An illustrated tour shows the concept; real venue imagery comes next.'],4:['MORE VISIBILITY','Manage the details that matter.','See service requests and feedback without chasing every table.'],5:['MORE FOCUSED SERVICE','Send help to the right table.','Specific requests let staff prioritise the floor.'],6:['LESS BILL HANDLING','Close the meal with less friction.','Guests can check every item and keep a digital receipt.'],7:['A REASON TO COME BACK','Hear it. Act on it.','Every rating reaches the owner; low scores flag a follow-up.' ]};
const safeText=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function logEvent(text){experienceState.events.unshift({text,time:new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})});experienceState.events=experienceState.events.slice(0,12)}
function syncBusiness(){const o=outcomes[scene];$('#business-signal').innerHTML=`<small>${o[0]}</small><b>${o[1]}</b><span>${o[2]}</span>`;$('#story-state').textContent=order?`Table ${order.table} · ${order.status} · ${currency(order.total)} ${order.paid?'· demo paid':''}`:'Tap the phone to see the business connection.';$('#connection-tag').textContent=scene===5&&experienceState.request?`Table ${experienceState.request.table} · ${experienceState.request.status}`:scene===2&&order?`Order → ${order.status}`:scene===7&&experienceState.feedback?'Feedback → owner':'';}
setScene=function(n){scene=n;$$('[data-scene]').forEach(b=>b.setAttribute('aria-selected',String(+b.dataset.scene===n)));$('#scene-number').textContent=`0${chapterOrder.indexOf(n)+1} / 08`;$('#scene-title').innerHTML=scenes[n][0];$('#scene-caption').textContent=scenes[n][1];$('#cafe').classList.toggle('kitchen-view',n===2);$('#cafe').classList.toggle('tour-view',n===3);$('#cafe').classList.toggle('routing',n===2&&!!order);$('.stage').classList.remove('scene-pulse');void $('.stage').offsetWidth;$('.stage').classList.add('scene-pulse');render();};
render=function(){if(scene===5)renderService();else if(scene===6)renderBill();else if(scene===7)renderFeedback();else originalRender();if(scene===2)$('#table-label').textContent=experienceState.guestTracking?`TABLE ${order?.table||table}`:'KITCHEN';if(scene===5)$('#table-label').textContent=`TABLE ${table}`;if(scene===6||scene===7)$('#table-label').textContent=`TABLE ${order?.table||table}`;syncBusiness()};
renderMenu=function(){const count=cart.length,total=cart.reduce((a,i)=>a+products[i].price,0);phone(`<div class="tiny-label">NO APP. NO WAIT TO ORDER.</div><h3>Your favourites.<br>At your pace.</h3><div class="menu-tabs">${['Coffee','Bites'].map(c=>`<button data-category="${c}" class="${menuCategory===c?'active':''}">${c==='Coffee'?'☕':'🥐'} ${c}</button>`).join('')}</div>${products.map((p,i)=>p.category===menuCategory?`<div class="food-row"><div class="food-icon">${p.icon}</div><div class="food-info"><b>${p.name}</b><small>${p.note}</small><strong>${currency(p.price)}</strong></div>${i===3&&experienceState.soldOut?'<span class="soldout">SOLD<br>OUT</span>':`<button class="add-item" data-add="${i}" aria-label="Add ${p.name}">${cart.filter(v=>v===i).length||'+'}</button>`}</div>`:'').join('')}<div class="menu-note">Prices include all demo charges. No hidden extras.</div><button class="primary" data-action="cart">${count?`View order (${count})`:'Choose something delicious'} <span>${count?currency(total):'+'}</span></button><button class="minor-link" data-growth="staff">Prefer a person? Call your waiter ↗</button>`)};
renderCart=function(){if(!cart.length){notify('Add something delicious to begin.');return}const total=cart.reduce((a,i)=>a+products[i].price,0);phone(`<div class="tiny-label">TABLE ${table} · YOUR ORDER</div><h3>Just as you like it.</h3>${[...new Set(cart)].map(i=>`<div class="cart-row"><span>${cart.filter(v=>v===i).length} × ${products[i].name}</span><button style="background:transparent;font-size:12px" data-remove="${i}" aria-label="Remove one ${products[i].name}">−</button></div>`).join('')}${cart.some(i=>i<3)&&!cart.includes(3)&&!experienceState.soldOut?'<div class="pairing"><span><strong>A little flaky company? 🥐</strong><small>Butter croissant · Optional · ₹140</small></span><button data-growth="pair">Add +</button></div>':''}<div class="cart-total"><span>Total</span><span>${currency(total)}</span></div><div class="menu-note">All demo charges included · No service charge</div><label class="pay-option"><input name="payment" type="radio" value="counter" checked> Pay after your meal</label><label class="pay-option"><input name="payment" type="radio" value="online"> Try paying now</label><button class="primary" data-action="order">Send to kitchen <span>↗</span></button><button class="secondary" data-action="back-menu">← Keep browsing</button><div class="phone-badge">Demo payment only. No money moves.</div>`)};
placeOrder=function(){const paid=$('input[name=payment]:checked')?.value==='online';order={items:[...cart],table,status:'received',total:cart.reduce((a,i)=>a+products[i].price,0),paid};cart=[];experienceState.feedback=null;experienceState.rating=0;experienceState.guestTracking=true;logEvent(`Table ${table}: ${order.items.length} items received · ${currency(order.total)}`);setScene(2);notify(`Table ${table} → Kitchen. No retyping needed.`)};
function renderGuestTracking(){$('#table-label').textContent=`TABLE ${order.table}`;const status=order.status,step=['received','preparing','ready','served'].indexOf(status);phone(`<div class="tiny-label">GUEST VIEW · TABLE ${order.table}</div><h3>${status==='served'?'Enjoy every bite.':'No need to ask<br>“is it ready?”'}</h3><p>See the same status as the kitchen.</p><div class="guest-track">${[['received','Order received'],['preparing','Being prepared'],['ready','Ready to serve'],['served','At your table']].map(([s,label],i)=>`<div class="${i<=step?'complete':''}"><b>${i<=step?'✓':i+1}</b><span>${label}</span><small>${i===step?'NOW':''}</small></div>`).join('')}</div><button class="primary" data-growth="kitchen-view">Open kitchen view <span>↗</span></button><div class="phone-utility"><button data-growth="staff">Call waiter</button><button data-growth="bill">View bill</button></div><div class="phone-badge">Interactive demo · Advance status in kitchen view</div>`)}
renderKitchen=function(){$('#table-label').textContent=experienceState.guestTracking?`TABLE ${order?.table||table}`:'KITCHEN';if(!order){phone(`<div class="tiny-label">KITCHEN + GUEST, CONNECTED</div><div class="empty-state"><span>♨</span><h3>See an order<br>travel through.</h3><p>Place your own order, or load a clearly labelled sample ticket.</p></div><button class="primary" data-growth="sample">Load sample order <span>↗</span></button><button class="minor-link" data-growth="menu">Order from the menu instead</button>`);return}if(experienceState.guestTracking){renderGuestTracking();return}const step=['received','preparing','ready','served'].indexOf(order.status);phone(`<div class="tiny-label">KITCHEN VIEW · ONE SHARED ORDER</div><h3>${order.status==='served'?'Served. In sync.':'The next right thing.'}</h3><div class="kitchen-ticket"><div class="ticket-top"><span>TABLE ${order.table}</span><small>${order.status.toUpperCase()}</small></div>${[...new Set(order.items)].map(i=>`<div class="ticket-item">${order.items.filter(v=>v===i).length} × ${products[i].name}</div>`).join('')}<div class="ticket-meta">${order.paid?'Demo paid':'Payment pending'} · ${currency(order.total)}</div></div><div class="ticket-timeline">${[0,1,2,3].map(i=>`<span class="${i<=step?'done':''}"></span>`).join('')}</div><button class="primary" data-action="advance">${['Start preparing','Ready to serve','Mark as served','Open digital bill'][step]} <span>↗</span></button><button class="tracking-switch" data-growth="guest-view">◎ Check what the guest sees</button><div class="phone-badge">Every change updates the guest view and owner view.</div>`)};
advance=function(){if(!order){loadSample();return}const sequence=['received','preparing','ready','served'],i=sequence.indexOf(order.status);if(i===3){setScene(6);return}order.status=sequence[i+1];logEvent(`Table ${order.table}: ${order.status}`);renderKitchen();syncBusiness();notify(`Kitchen → Guest: ${order.status}.`)};
function loadSample(){order={items:[0,3],table,status:'received',total:320,paid:false,sample:true};experienceState.feedback=null;experienceState.rating=0;experienceState.guestTracking=false;logEvent(`Sample order loaded for table ${table}`);setScene(2);notify('Sample ticket loaded. Advance it through the kitchen.')}
function renderService(){$('#table-label').textContent=`TABLE ${table}`;const r=experienceState.request;phone(`<div class="tiny-label">GUEST ↔ FLOOR TEAM</div><h3>A hand, right<br>when you need it.</h3><p>Choose the request. Your table goes with it.</p><div class="request-grid"><button data-request="Water refill"><span>♧</span>Water refill</button><button data-request="Help ordering"><span>☷</span>Help ordering</button><button data-request="Allergy question"><span>✳</span>Allergy question</button><button data-request="The bill"><span>▤</span>The bill</button></div>${r?`<div class="request-status"><b>Table ${r.table} · ${safeText(r.type)}</b><span>${r.status==='sent'?'Sent to the team':r.status==='acknowledged'?'A team member is on the way':'Request completed ✓'}</span></div><button class="primary" data-growth="service-team">See the team’s view <span>↗</span></button>`:'<div class="phone-badge">No waving. No shouting across the room.</div>'}<button class="minor-link" data-growth="menu">← Back to your menu</button>`)}
function renderServiceTeam(){$('#table-label').textContent='FLOOR TEAM';const r=experienceState.request;phone(`<div class="tiny-label">FLOOR TEAM · REQUEST QUEUE</div><h3>The right help.<br>The right table.</h3><p>See exactly what the guest needs.</p>${r?`<div class="kitchen-ticket"><div class="ticket-top"><span>TABLE ${r.table}</span><small>${r.status==='sent'?'NEW':r.status.toUpperCase()}</small></div><div class="ticket-item">${safeText(r.type)}</div><div class="ticket-meta">${r.type==='Allergy question'?'Discuss directly with the guest before ordering.':'Request created in this demo.'}</div></div><button class="primary" data-growth="service-advance">${r.status==='sent'?'Acknowledge · On my way':r.status==='acknowledged'?'Mark as completed':'Back to guest view'} <span>✓</span></button>`:'<p>No active request.</p>'}<button class="minor-link" data-growth="service-guest">◎ Check the guest’s update</button>`)}
function emptyOrder(label){phone(`<div class="tiny-label">ONE CONNECTED JOURNEY</div><div class="empty-state"><span>${label==='bill'?'▤':'♡'}</span><h3>${label==='bill'?'Every item.<br>Out in the open.':'A better next visit<br>starts here.'}</h3><p>${label==='bill'?'Order first to see its itemised digital bill.':'Feedback connects to a served order.'}</p></div><button class="primary" data-growth="${label==='bill'?'sample-bill':'sample-feedback'}">Try with a sample order <span>↗</span></button><button class="minor-link" data-growth="menu">Build your own order</button>`)}
function renderBill(){if(!order){emptyOrder('bill');return}phone(`<div class="tiny-label">DIGITAL ${order.paid?'RECEIPT':'BILL'} · TABLE ${order.table}</div><h3>Clear to the<br>last coffee.</h3><div class="receipt-paper"><small>GOOD DAYS · ${order.paid?'DEMO PAID':'NOT YET PAID'}</small>${[...new Set(order.items)].map(i=>`<div class="cart-row"><span>${order.items.filter(v=>v===i).length} × ${products[i].name}</span><span>${currency(order.items.filter(v=>v===i).length*products[i].price)}</span></div>`).join('')}<div class="receipt-line"><span>Extra fees / service charge</span><span>₹0</span></div><div class="cart-total"><span>Total</span><span>${currency(order.total)}</span></div><small>All demo charges included · Not a tax invoice</small></div>${order.paid?'<button class="primary" data-growth="download-receipt">Keep digital receipt <span>↓</span></button>':'<button class="primary" data-growth="settle">Simulate payment <span>✓</span></button>'}<div class="phone-utility"><button data-growth="feedback">Leave feedback</button><button data-growth="staff">Ask your waiter</button></div><div class="phone-badge">No contact details required. No real transaction.</div>`)}
function renderFeedback(){if(!order){emptyOrder('feedback');return}if(order.status!=='served'){phone(`<div class="tiny-label">AFTER THE MEAL</div><h3>First, a good meal.<br>Then, your thoughts.</h3><p>Your order is ${order.status}. Mark it served in the kitchen to try the feedback flow.</p><div class="success-icon">♨</div><button class="primary" data-growth="kitchen-view">Go to the kitchen <span>↗</span></button>`);return}if(experienceState.feedback){phone(`<div class="tiny-label">FEEDBACK DELIVERED</div><div class="success-icon">♡</div><h3>Heard. Thank you.</h3><p>Your ${experienceState.feedback.rating}-star feedback for table ${order.table} is now in the owner’s view.</p><div class="owner-alert good"><b>${experienceState.feedback.rating<=3?'A follow-up is flagged.':'A good moment, captured.'}</b>Every rating helps the team improve.</div><button class="primary" data-growth="owner-feedback">See the owner’s view <span>↗</span></button><button class="minor-link" data-extra="loyalty">Explore a reason to come back ✳</button>`);return}phone(`<div class="tiny-label">PRIVATE FEEDBACK · TABLE ${order.table}</div><h3>How did we<br>make you feel?</h3><div class="rating-picker" role="group" aria-label="Rate your visit">${[1,2,3,4,5].map(n=>`<button data-rating="${n}" class="${n<=experienceState.rating?'chosen':''}" aria-label="${n} star${n>1?'s':''}" aria-pressed="${n===experienceState.rating}">★</button>`).join('')}</div><label class="feedback-label" for="visit-note">A little more? (optional)</label><textarea id="visit-note" class="feedback-note" maxlength="240" placeholder="What went well? What could be better?"></textarea><button class="primary feedback-submit" data-growth="send-feedback" ${experienceState.rating?'':'disabled'}>Share with the owner <span>↗</span></button><div class="phone-badge">Demo only · All ratings reach the owner.</div>`)}
renderDashboard=function(){const tabName=experienceState.ownerTab,served=order?.status==='served',f=experienceState.feedback,r=experienceState.request;let content='';if(tabName==='overview')content=`<div class="metric-grid"><div class="metric"><small>DEMO SALES PAID</small><b>${currency(order?.paid?order.total:0)}</b></div><div class="metric"><small>DEMO ORDERS</small><b>${order?1:0}</b></div><div class="metric"><small>STAFF REQUESTS OPEN</small><b>${r&&r.status!=='completed'?1:0}</b></div><div class="metric"><small>FEEDBACK RECEIVED</small><b>${f?1:0}</b></div></div><div class="owner-alert ${served?'good':''}"><b>${order?`Table ${order.table} · ${order.status}`:'Ready for your first demo order.'}</b>${order?`${order.items.length} items · ${currency(order.total)} · ${order.paid?'Demo paid':'Payment pending'}`:'Actions in the guest view update these figures.'}</div><div class="availability"><span>Butter croissant</span><button data-growth="availability" class="${experienceState.soldOut?'off':''}">${experienceState.soldOut?'Sold out → enable':'Available → hide'}</button></div><button class="minor-link" data-growth="check-menu">See the live menu change ↗</button>`;
if(tabName==='feedback')content=f?`<div class="owner-alert ${f.rating>3?'good':''}"><b>${'★'.repeat(f.rating)}${'☆'.repeat(5-f.rating)} · TABLE ${f.table}</b>${f.note?safeText(f.note):'No written comment.'}</div><p>${f.rating<=3?'Follow-up suggested: check in with the guest and understand what happened.':'A positive visit. Keep the details that made it work.'}</p><div class="table-status-chip">${f.resolved?'Reviewed ✓':f.rating<=3?'NEEDS FOLLOW-UP':'NEW FEEDBACK'}</div><button class="primary" data-growth="review-feedback">${f.resolved?'Review recorded':'Mark as reviewed'} <span>✓</span></button><div class="phone-badge">Private feedback · No public review is posted.</div>`:'<div class="empty-state"><span>♡</span><p>No feedback yet. Complete the guest journey to try it.</p></div><button class="primary" data-growth="feedback">Open guest feedback <span>↗</span></button>';
if(tabName==='activity')content=`<div class="owner-activity">${experienceState.events.length?experienceState.events.map(e=>`<div><time>${e.time}</time>${safeText(e.text)}</div>`).join(''):'Your demo actions will appear here.'}</div>${r?`<div class="request-line"><span>Table ${r.table}: ${safeText(r.type)}<br>${r.status}</span><button data-growth="owner-request">Open request</button></div>`:''}`;
phone(`<div class="tiny-label">OWNER VIEW · YOUR DEMO ACTIVITY</div><h3>A clearer kind<br>of control.</h3><div class="owner-tabs">${['overview','feedback','activity'].map(t=>`<button data-owner-tab="${t}" class="${t===tabName?'active':''}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div>${content}`)};
showExtra=function(type){if(type==='staff'){stopTour();setScene(5);$('#playground').scrollIntoView({behavior:'smooth'});return}originalShowExtra(type)};
startTour=function(){if(tourTimer){stopTour();return}setScene(0);$('#auto-tour').textContent='Ⅱ Pause the story';tourTimer=setInterval(()=>{const i=chapterOrder.indexOf(scene);if(i===chapterOrder.length-1){stopTour();return}setScene(chapterOrder[i+1])},6500)};
function downloadText(name,text){const blob=new Blob([text],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function downloadReceipt(){downloadText(`rawcoderz-demo-table-${order.table}.txt`,`GOOD DAYS — DEMO RECEIPT\nTable ${order.table}\n${order.paid?'DEMO PAID':'NOT PAID'}\n\n${[...new Set(order.items)].map(i=>`${order.items.filter(v=>v===i).length} x ${products[i].name}: ${currency(order.items.filter(v=>v===i).length*products[i].price)}`).join('\n')}\n\nExtra fees / service charge: ₹0\nTotal: ${currency(order.total)}\nAll demo charges included.\n\nThis is a simulated receipt, not a tax invoice.\nNo real transaction was processed.\nRawcoderz hospitality concept.`);logEvent(`Table ${order.table}: digital receipt downloaded`);notify('Digital demo receipt downloaded. No paper needed.')}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const action=b.dataset.growth;if(action||b.dataset.request||b.dataset.rating||b.dataset.ownerTab)stopTour();if(action==='menu')setScene(1);if(action==='staff')setScene(5);if(action==='bill')setScene(6);if(action==='feedback')setScene(7);if(action==='sample')loadSample();if(action==='sample-bill'||action==='sample-feedback'){loadSample();order.status='served';logEvent('Sample order marked served');setScene(action==='sample-bill'?6:7)}if(action==='pair'){if(cart.length>=9){notify('This demo supports 9 items per order.');return}cart.push(3);renderCart();notify('Croissant added explicitly · +₹140')}if(action==='kitchen-view'){experienceState.guestTracking=false;setScene(2)}if(action==='guest-view'){experienceState.guestTracking=true;renderKitchen()}if(b.dataset.request){experienceState.request={table,type:b.dataset.request,status:'sent'};logEvent(`Table ${table}: ${b.dataset.request} requested`);renderService();syncBusiness();notify(`Table ${table} request sent to the floor team.`)}if(action==='service-team')renderServiceTeam();if(action==='service-guest')renderService();if(action==='service-advance'){const r=experienceState.request;if(r.status==='completed'){renderService();return}r.status=r.status==='sent'?'acknowledged':'completed';logEvent(`Table ${r.table}: request ${r.status}`);renderServiceTeam();syncBusiness();notify(`Guest updated: ${r.status==='acknowledged'?'a team member is on the way':'request completed'}.`)}if(action==='settle'){order.paid=true;logEvent(`Table ${order.table}: demo payment ${currency(order.total)} confirmed`);renderBill();syncBusiness();notify('Demo payment confirmed. Your digital receipt is ready.')}if(action==='download-receipt')downloadReceipt();if(b.dataset.rating){const note=$('#visit-note')?.value||'';experienceState.rating=+b.dataset.rating;renderFeedback();$('#visit-note').value=note}if(action==='send-feedback'&&experienceState.rating){experienceState.feedback={rating:experienceState.rating,note:$('#visit-note').value.trim(),table:order.table,resolved:false};logEvent(`Table ${order.table}: ${experienceState.rating}-star feedback received`);renderFeedback();syncBusiness();notify('Feedback received in the owner view.')}if(action==='owner-feedback'){experienceState.ownerTab='feedback';setScene(4)}if(action==='review-feedback'){experienceState.feedback.resolved=true;logEvent(`Table ${experienceState.feedback.table}: feedback reviewed`);renderDashboard();notify('Feedback marked reviewed in this demo.')}if(b.dataset.ownerTab){experienceState.ownerTab=b.dataset.ownerTab;renderDashboard()}if(action==='owner-request'){table=experienceState.request.table;setScene(5);renderServiceTeam()}if(action==='availability'){experienceState.soldOut=!experienceState.soldOut;if(experienceState.soldOut)cart=cart.filter(i=>i!==3);logEvent(`Butter croissant ${experienceState.soldOut?'marked sold out':'available again'}`);renderDashboard();notify(`Guest menu updated: croissant ${experienceState.soldOut?'sold out':'available'}.`)}if(action==='check-menu'){menuCategory='Bites';setScene(1)}if(b.dataset.shift)setShift(b.dataset.shift);if(action==='download-plan')downloadPlan();});
function setShift(mode){const smart=mode==='connected';$$('[data-shift]').forEach(b=>b.classList.toggle('active',b.dataset.shift===mode));$$('[data-shift]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.shift===mode)));$('#shift-title').textContent=smart?'More hospitality. Fewer errands.':'Good people. Too many handoffs.';$('#shift-description').textContent=smart?'Ordering, status and billing move digitally. Your people focus on welcoming, serving and helping.':'Your team takes the order, re-enters it, checks progress, carries the bill and collects payment.';$('#staff-touch-count').textContent=smart?'2':'6';$('#shift-status').textContent=smart?'Digital handoffs handle the routine. Staff handle the human moments.':'Each manual handoff competes for your team’s attention.';$$('.shift-task').forEach(el=>{const automated=smart&&el.dataset.automate==='true';el.classList.toggle('automated',automated);el.querySelector('i').textContent=automated?'✓':'↗';el.querySelector('small').textContent=automated?'DIGITAL':'TEAM'});$('#shift-floor').classList.toggle('connected',smart)}
function calculateImpact(){const n=id=>Number($('#'+id).value),daily=n('daily-orders'),adoption=n('digital-share'),minutes=n('minutes-saved'),days=n('open-days'),take=n('addon-take'),price=n('addon-price');if(![daily,adoption,minutes,days,take,price].every(Number.isFinite)||days<1||days>31||take<0||take>100||price<0){$('#calc-error').textContent='Use 1–31 operating days, 0–100% add-on take-up and a non-negative add-on price.';$('#hours-result').textContent='—';$('#sales-result').textContent='—';$('#paper-result').textContent='—';$('#formula-detail').textContent='Correct the highlighted assumptions to calculate a scenario.';return}$('#calc-error').textContent='';$('#daily-output').textContent=daily;$('#share-output').textContent=adoption+'%';$('#minutes-output').textContent=minutes+' min';const digital=daily*days*adoption/100;$('#hours-result').textContent=(digital*minutes/60).toLocaleString('en-IN',{maximumFractionDigits:1})+' hrs';$('#sales-result').textContent=currency(Math.round(digital*take/100*price));$('#paper-result').textContent=Math.round(digital).toLocaleString('en-IN');$('#formula-detail').textContent=`${daily} orders/day × ${days} days × ${adoption}% digital adoption = ${Math.round(digital).toLocaleString('en-IN')} digital orders/month. Time: digital orders × ${minutes} minutes ÷ 60. Extra gross sales: digital orders × ${take}% add-on take-up × ₹${price}. Paper: assumes one digital receipt replaces one printed bill per digital order.`;}
function updateBlueprint(){const picks=$$('.module-choice input:checked').map(e=>e.value);$('#module-count').textContent=`${picks.length} connected ${picks.length===1?'module':'modules'}. Your way.`;$('#blueprint-tags').innerHTML=picks.map(p=>`<span>${safeText(p)}</span>`).join('')||'<span>Select the pieces your venue needs.</span>';$('#download-plan').disabled=!picks.length}
function downloadPlan(){const picks=$$('.module-choice input:checked').map(e=>e.value),venue=$('#venue-type').value;downloadText('rawcoderz-hospitality-brief.txt',`RAW CODERZ — HOSPITALITY DISCOVERY BRIEF\n\nVenue: ${venue}\nSelected concepts:\n${picks.map(p=>'• '+p).join('\n')}\n\nBusiness priorities:\nReduce repetitive order/bill handling; improve order visibility; make guest requests clear; gather feedback; support repeat visits.\n\nBefore implementation, confirm:\n• Table count and service model\n• Current POS and available integration APIs\n• Menu, modifiers, kitchen stations and tax settings\n• Payment provider, receipts and settlement flow\n• Internet reliability and staff-assisted fallback\n• Staff roles, feedback handling and guest consent\n\nThis is a locally generated planning brief, not a quote or submitted enquiry. No data has been sent to Rawcoderz. Integrations, cost and scope need validation.`);notify('Your custom demo brief is downloaded. Nothing was submitted.')}
function setupGrowth(){const nav=[['⌗','Scan & order',0],['▤','Smart menu',1],['♨','Order tracking',2],['♧','Call waiter',5],['▤','Digital bill',6],['♡','Feedback',7],['↗','Owner view',4],['◎','Virtual café',3]];$('.chapter-nav').innerHTML=nav.map(([icon,label,n],i)=>`<button role="tab" aria-selected="${n===0}" data-scene="${n}"><span class="chapter-icon">${icon}</span><span><small>0${i+1}</small>${label}</span></button>`).join('');$('.stage').insertAdjacentHTML('beforeend','<div class="business-signal" id="business-signal" aria-live="polite"></div><div class="story-state" id="story-state"></div><div class="connection-tag" id="connection-tag"></div>');$$('[role=tab]').forEach((b,i)=>b.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();const next=(i+(e.key==='ArrowRight'?1:7))%8;stopTour();setScene(chapterOrder[next]);$$('[role=tab]')[next].focus()}}));$('#auto-tour').onclick=startTour;$('#tour-top').onclick=()=>{$('#playground').scrollIntoView({behavior:'smooth'});if(!tourTimer)startTour()};$('#restart').onclick=()=>{stopTour();order=null;cart=[];table='04';experienceState.request=null;experienceState.feedback=null;experienceState.rating=0;experienceState.events=[];experienceState.soldOut=false;experienceState.ownerTab='overview';setScene(0);$('#playground').scrollIntoView({behavior:'smooth'})};$$('.growth-input input,.assumption-row input').forEach(e=>e.addEventListener('input',calculateImpact));$$('.module-choice input').forEach(e=>e.addEventListener('change',updateBlueprint));setShift('connected');calculateImpact();updateBlueprint();setScene(0)}
setupGrowth();

// The guided story demonstrates state changes instead of only switching tabs.
startTour=function(){
  if(tourTimer){stopTour();return}
  const stages=[
    ()=>setScene(0),
    ()=>{menuCategory='Coffee';setScene(1)},
    ()=>{if(!order){order={items:[0,3],table,status:'received',total:320,paid:false,sample:true};logEvent(`Guided sample: table ${table} order received`)}experienceState.guestTracking=false;setScene(2)},
    ()=>{order.status='preparing';experienceState.guestTracking=true;logEvent(`Table ${order.table}: preparing`);setScene(2)},
    ()=>{experienceState.request={table:order.table,type:'Water refill',status:'sent'};logEvent(`Table ${order.table}: water requested`);setScene(5)},
    ()=>{experienceState.request.status='acknowledged';renderServiceTeam();syncBusiness()},
    ()=>{order.status='served';order.paid=true;logEvent(`Table ${order.table}: served and demo paid`);setScene(6)},
    ()=>{experienceState.feedback={rating:5,note:'Loved the easy ordering and clear bill.',table:order.table,resolved:false};logEvent(`Table ${order.table}: sample feedback received`);setScene(7)},
    ()=>{experienceState.ownerTab='overview';setScene(4)},
    ()=>{tourView='cafe';setScene(3)}
  ];
  let index=0;stages[0]();$('#auto-tour').textContent='Ⅱ Pause the story';notify('Guided demo: watch an example visit connect the whole team.');
  tourTimer=setInterval(()=>{index++;if(index>=stages.length){stopTour();notify('Story complete. Explore any scene or restart the journey.');return}stages[index]()},5200);
};
$('#auto-tour').onclick=startTour;
$('#tour-top').onclick=()=>{$('#playground').scrollIntoView({behavior:'smooth'});if(!tourTimer)startTour()};
// Pause guided playback as soon as a visitor starts interacting with a scene.
document.addEventListener('click',e=>{if(e.target.closest('.phone button,.hotspot,.chapter-nav button'))stopTour()},true);
